SELECT i.id AS issue_id, i.title AS title, i.category AS category, i.severity AS severity, i.confidence AS confidence, i.file_id AS file_id, f.file_path AS file_path, i.start_line AS start_line, i.end_line AS end_line, i.feedback_status AS feedback_status, i.update_time AS update_time FROM review_issue i LEFT JOIN task_file f ON f.id = i.file_id AND f.task_id = i.task_id WHERE i.task_id = #{taskId}
AND i.severity IN
#{item}
AND i.category IN
#{item}
AND i.feedback_status IN
#{item}
AND i.file_id = #{param.fileId}
AND ( i.title LIKE CONCAT('%', #{param.keyword}, '%') OR i.trigger_condition LIKE CONCAT('%', #{param.keyword}, '%') OR i.impact LIKE CONCAT('%', #{param.keyword}, '%') OR i.evidence LIKE CONCAT('%', #{param.keyword}, '%') )
ORDER BY i.severity ASC, i.id ASC
ORDER BY i.create_time ASC, i.id ASC
ORDER BY i.create_time DESC, i.id DESC
ORDER BY i.severity DESC, i.id ASC
